-- Compact independent intentions. Financial debit/ledger/post29 are deliberately untouched.
CREATE TABLE IF NOT EXISTS astra_tarot31_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),version TEXT NOT NULL DEFAULT 'tarot31-v1' CHECK(version='tarot31-v1'),migration_done INTEGER NOT NULL DEFAULT 0 CHECK(migration_done IN(0,1)),enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),questions_enabled INTEGER NOT NULL DEFAULT 0 CHECK(questions_enabled IN(0,1)),cleanup_enabled INTEGER NOT NULL DEFAULT 0 CHECK(cleanup_enabled IN(0,1)),max_open INTEGER NOT NULL DEFAULT 5 CHECK(typeof(max_open)='integer' AND max_open BETWEEN 1 AND 20),burst_limit INTEGER NOT NULL DEFAULT 20 CHECK(typeof(burst_limit)='integer' AND burst_limit BETWEEN 4 AND 100),revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(revision)='integer' AND revision>=0));
INSERT OR IGNORE INTO astra_tarot31_policy(singleton)VALUES(1);
CREATE TRIGGER IF NOT EXISTS astra_tarot31_policy_insert BEFORE INSERT ON astra_tarot31_policy WHEN EXISTS(SELECT 1 FROM astra_tarot31_policy)BEGIN SELECT RAISE(IGNORE);END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_policy_delete BEFORE DELETE ON astra_tarot31_policy BEGIN SELECT RAISE(ABORT,'Policy31 required');END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_policy_update BEFORE UPDATE ON astra_tarot31_policy BEGIN
 SELECT CASE WHEN NEW.singleton<>OLD.singleton OR NEW.version<>OLD.version OR NEW.revision<OLD.revision OR(OLD.migration_done=1 AND NEW.migration_done<>1) OR((NEW.enabled OR NEW.questions_enabled OR NEW.cleanup_enabled)AND NEW.migration_done<>1) THEN RAISE(ABORT,'Policy31 transition') END;
 SELECT CASE WHEN(NEW.max_open<>OLD.max_open OR NEW.burst_limit<>OLD.burst_limit)AND(NEW.enabled OR OLD.enabled OR NEW.cleanup_enabled OR OLD.cleanup_enabled OR NEW.questions_enabled OR OLD.questions_enabled OR NEW.revision<>OLD.revision+1)THEN RAISE(ABORT,'Policy31 close gates and revise') END;
END;
CREATE TABLE IF NOT EXISTS astra_tarot31_intents(offer_id TEXT PRIMARY KEY NOT NULL CHECK(length(offer_id)=32 AND offer_id NOT GLOB '*[^a-f0-9]*'),telegram_id INTEGER NOT NULL REFERENCES astra_users(telegram_id)ON DELETE CASCADE,generation TEXT NOT NULL,request_key TEXT NOT NULL CHECK(length(request_key)BETWEEN 1 AND 128),update_id INTEGER NOT NULL CHECK(typeof(update_id)='integer' AND update_id>=0),spread_id TEXT NOT NULL,theme TEXT NOT NULL CHECK(theme IN('general','relations','work','choice','resources')),price INTEGER NOT NULL,price_version TEXT NOT NULL,policy_revision INTEGER NOT NULL,intent_revision INTEGER NOT NULL,seed TEXT NOT NULL CHECK(length(seed)=64 AND seed NOT GLOB '*[^a-f0-9]*'),state TEXT NOT NULL DEFAULT 'quoted' CHECK(state IN('quoted','sealing','sealed','paid','cancelled')),lease TEXT,lease_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL DEFAULT(unixepoch()),expires_at INTEGER NOT NULL CHECK(expires_at=created_at+900),UNIQUE(telegram_id,generation,request_key),UNIQUE(telegram_id,generation,update_id));
CREATE INDEX IF NOT EXISTS idx_tarot31_intent_owner ON astra_tarot31_intents(telegram_id,generation,state,expires_at);
CREATE TABLE IF NOT EXISTS astra_tarot31_receipts(telegram_id INTEGER NOT NULL REFERENCES astra_users(telegram_id)ON DELETE CASCADE,generation TEXT NOT NULL,request_key TEXT NOT NULL,update_id INTEGER NOT NULL,offer_id TEXT NOT NULL UNIQUE,spread_id TEXT NOT NULL,theme TEXT NOT NULL,PRIMARY KEY(telegram_id,generation,request_key),UNIQUE(telegram_id,generation,update_id));
CREATE TABLE IF NOT EXISTS astra_tarot31_burst(telegram_id INTEGER NOT NULL REFERENCES astra_users(telegram_id)ON DELETE CASCADE,generation TEXT NOT NULL,window INTEGER NOT NULL,used INTEGER NOT NULL CHECK(typeof(used)='integer' AND used>=0),PRIMARY KEY(telegram_id,generation,window));
CREATE TRIGGER IF NOT EXISTS astra_tarot31_intent_insert BEFORE INSERT ON astra_tarot31_intents BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_receipts WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND(request_key=NEW.request_key OR update_id=NEW.update_id))THEN RAISE(ABORT,'INTENT_REQUEST_SEEN') END;
 SELECT CASE WHEN NEW.state<>'quoted' OR NEW.lease IS NOT NULL OR NEW.lease_until<>0 OR NEW.created_at<>unixepoch() OR NOT EXISTS(SELECT 1 FROM astra_users u JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_prices29 t ON t.price_version=r.price_version AND t.spread_id=NEW.spread_id WHERE u.telegram_id=NEW.telegram_id AND g.generation=NEW.generation AND r.enabled=1 AND r.migration_done=1 AND s.migration_done=1 AND s.write_enabled=1 AND p.migration_done=1 AND p.enabled=1 AND p.revision=NEW.intent_revision AND r.revision=NEW.policy_revision AND NEW.price_version=t.price_version AND NEW.price=t.price AND(t.theme='general' OR t.theme=NEW.theme))THEN RAISE(ABORT,'INTENT_GATE_OR_OWNER')END;
 SELECT CASE WHEN(SELECT count(*) FROM astra_tarot31_intents WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND state IN('quoted','sealing','sealed') AND expires_at>unixepoch())>=(SELECT max_open FROM astra_tarot31_policy)THEN RAISE(ABORT,'INTENT_OPEN_LIMIT')END;
 SELECT CASE WHEN coalesce((SELECT used FROM astra_tarot31_burst WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND window=unixepoch()/60),0)>=(SELECT burst_limit FROM astra_tarot31_policy)THEN RAISE(ABORT,'INTENT_BURST_LIMIT')END;
 SELECT CASE WHEN(SELECT page_count FROM pragma_page_count)*(SELECT page_size FROM pragma_page_size)+65536>(SELECT soft_cap_bytes FROM astra_tarot30_policy)THEN RAISE(ABORT,'DRAFT_STORAGE_SOFT_CAP')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_intent_post AFTER INSERT ON astra_tarot31_intents BEGIN
 INSERT INTO astra_tarot31_receipts VALUES(NEW.telegram_id,NEW.generation,NEW.request_key,NEW.update_id,NEW.offer_id,NEW.spread_id,NEW.theme);
 INSERT INTO astra_tarot31_burst VALUES(NEW.telegram_id,NEW.generation,unixepoch()/60,1)ON CONFLICT(telegram_id,generation,window)DO UPDATE SET used=used+1;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_receipt_insert BEFORE INSERT ON astra_tarot31_receipts BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_receipts WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND(request_key=NEW.request_key OR update_id=NEW.update_id))OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i WHERE i.offer_id=NEW.offer_id AND i.telegram_id=NEW.telegram_id AND i.generation=NEW.generation AND i.request_key=NEW.request_key AND i.update_id=NEW.update_id AND i.spread_id=NEW.spread_id AND i.theme=NEW.theme)THEN RAISE(ABORT,'INTENT_RECEIPT_AUTHORITY')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_receipt_update BEFORE UPDATE ON astra_tarot31_receipts BEGIN SELECT RAISE(ABORT,'Intent receipt immutable');END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_receipt_delete BEFORE DELETE ON astra_tarot31_receipts WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN SELECT RAISE(ABORT,'Erase receipt with profile');END;
CREATE TABLE IF NOT EXISTS astra_tarot31_questions(offer_id TEXT PRIMARY KEY NOT NULL REFERENCES astra_tarot31_intents(offer_id)ON DELETE CASCADE,policy_version TEXT NOT NULL CHECK(policy_version='tarot-question-consent-v1'),consented_at INTEGER NOT NULL DEFAULT(unixepoch()),consent_update INTEGER NOT NULL CHECK(typeof(consent_update)='integer' AND consent_update>=0),consent_message INTEGER NOT NULL CHECK(typeof(consent_message)='integer' AND consent_message>0),text TEXT CHECK(text IS NULL OR(length(text)BETWEEN 1 AND 500 AND length(CAST(text AS BLOB))<=2000)),text_update INTEGER CHECK(text_update IS NULL OR(typeof(text_update)='integer' AND text_update>consent_update)));
CREATE TRIGGER IF NOT EXISTS astra_tarot31_question_insert BEFORE INSERT ON astra_tarot31_questions BEGIN
 SELECT CASE WHEN NEW.consented_at<>unixepoch() OR NEW.text IS NOT NULL OR NEW.text_update IS NOT NULL OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE r.enabled=1 AND s.write_enabled=1 AND i.offer_id=NEW.offer_id AND g.generation=i.generation AND i.state='quoted' AND i.expires_at>unixepoch() AND p.enabled=1 AND p.questions_enabled=1) OR EXISTS(SELECT 1 FROM astra_tarot31_questions q JOIN astra_tarot31_intents x ON x.offer_id=q.offer_id JOIN astra_tarot31_intents i ON i.offer_id=NEW.offer_id WHERE x.telegram_id=i.telegram_id AND x.generation=i.generation AND x.state='quoted' AND x.expires_at>unixepoch() AND q.text IS NULL AND x.offer_id<>i.offer_id)THEN RAISE(ABORT,'QUESTION_CONSENT_AUTHORITY')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_question_update BEFORE UPDATE ON astra_tarot31_questions BEGIN
 SELECT CASE WHEN NEW.offer_id<>OLD.offer_id OR NEW.policy_version<>OLD.policy_version OR NEW.consented_at<>OLD.consented_at OR NEW.consent_update<>OLD.consent_update OR NEW.consent_message<>OLD.consent_message OR OLD.text IS NOT NULL OR NEW.text IS NULL OR NEW.text_update IS NULL OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE r.enabled=1 AND s.write_enabled=1 AND i.offer_id=NEW.offer_id AND i.generation=g.generation AND i.state='quoted' AND i.expires_at>unixepoch() AND p.enabled=1 AND p.questions_enabled=1)THEN RAISE(ABORT,'QUESTION_IMMUTABLE_OR_EXPIRED')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_question_delete BEFORE DELETE ON astra_tarot31_questions WHEN EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_users u USING(telegram_id) WHERE i.offer_id=OLD.offer_id AND i.state IN('sealing','sealed'))BEGIN SELECT RAISE(ABORT,'Question sealed');END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_intent_update BEFORE UPDATE ON astra_tarot31_intents BEGIN
 SELECT CASE WHEN NEW.offer_id IS NOT OLD.offer_id OR NEW.telegram_id IS NOT OLD.telegram_id OR NEW.generation IS NOT OLD.generation OR NEW.request_key IS NOT OLD.request_key OR NEW.update_id IS NOT OLD.update_id OR NEW.spread_id IS NOT OLD.spread_id OR NEW.theme IS NOT OLD.theme OR NEW.price IS NOT OLD.price OR NEW.price_version IS NOT OLD.price_version OR NEW.policy_revision IS NOT OLD.policy_revision OR NEW.intent_revision IS NOT OLD.intent_revision OR NEW.seed IS NOT OLD.seed OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at THEN RAISE(ABORT,'Intent identity immutable')END;
 SELECT CASE WHEN NOT((OLD.state='quoted' OR(OLD.state='sealing' AND OLD.lease_until<=unixepoch()))AND NEW.state='sealing' AND NEW.lease IS NOT NULL AND NEW.lease IS NOT OLD.lease AND NEW.lease_until=unixepoch()+30 AND OLD.expires_at>unixepoch() AND EXISTS(SELECT 1 FROM astra_users u JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 JOIN astra_tarot31_policy p ON p.singleton=1 WHERE u.telegram_id=OLD.telegram_id AND g.generation=OLD.generation AND u.balance>=OLD.price AND r.enabled=1 AND r.revision=OLD.policy_revision AND s.write_enabled=1 AND p.enabled=1 AND p.revision=OLD.intent_revision) AND NOT EXISTS(SELECT 1 FROM astra_tarot31_questions WHERE offer_id=OLD.offer_id AND text IS NULL)
 OR OLD.state='sealing' AND NEW.state='sealed' AND NEW.lease IS NULL AND NEW.lease_until=0 AND EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=OLD.offer_id)
 OR OLD.state='sealed' AND NEW.state='paid' AND NEW.lease IS NULL AND NEW.lease_until=0 AND EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=OLD.offer_id)
 OR OLD.state IN('quoted','sealed') AND NEW.state='cancelled' AND NEW.lease IS NULL AND NEW.lease_until=0 AND NOT EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=OLD.offer_id))THEN RAISE(ABORT,'INTENT_STATE_OR_FUNDS')END;
END;
-- New offers require the private compact intention, including its lease and fixed question.
DROP TRIGGER IF EXISTS astra_tarot30_offer_admission;
CREATE TRIGGER astra_tarot30_offer_admission BEFORE INSERT ON astra_tarot25_offers29 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=NEW.offer_id)THEN RAISE(IGNORE)END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE i.offer_id=NEW.offer_id AND i.telegram_id=NEW.telegram_id AND i.generation=NEW.generation AND i.request_key=NEW.request_key AND i.update_id=NEW.update_id AND i.spread_id=NEW.spread_id AND i.theme=NEW.theme AND i.price=NEW.price AND i.policy_revision=NEW.policy_revision AND i.state='sealing' AND i.lease_until>unixepoch() AND i.expires_at>unixepoch() AND p.enabled=1 AND p.revision=i.intent_revision AND s.write_enabled=1 AND json_extract(NEW.snapshot_json,'$.created_at')=strftime('%Y-%m-%dT%H:%M:%fZ',i.created_at,'unixepoch') AND json_extract(NEW.snapshot_json,'$.question') IS(SELECT text FROM astra_tarot31_questions WHERE offer_id=i.offer_id))THEN RAISE(ABORT,'INTENT_SEAL_AUTHORITY')END;
 SELECT CASE WHEN json_type(NEW.snapshot_json,'$.question')='text' AND NOT EXISTS(SELECT 1 FROM astra_tarot31_questions q WHERE q.offer_id=NEW.offer_id AND q.text=json_extract(NEW.snapshot_json,'$.question') AND q.policy_version=json_extract(NEW.snapshot_json,'$.question_proof.policy_version') AND q.consented_at=json_extract(NEW.snapshot_json,'$.question_proof.consented_at') AND q.consent_update=json_extract(NEW.snapshot_json,'$.question_proof.consent_update') AND q.consent_message=json_extract(NEW.snapshot_json,'$.question_proof.consent_message'))THEN RAISE(ABORT,'QUESTION_PROOF_MISMATCH')END;
 SELECT CASE WHEN NEW.engine_version<>'tarot25-v2' OR json_extract(NEW.snapshot_json,'$.text_version') IS NOT 'rws78-interpretation-v2' THEN RAISE(ABORT,'INTENT_TEXT_VERSION')END;
 SELECT CASE WHEN(SELECT page_count FROM pragma_page_count)*(SELECT page_size FROM pragma_page_size)+2*(length(CAST(NEW.snapshot_json AS BLOB))+length(CAST(NEW.result AS BLOB)))+65536>(SELECT soft_cap_bytes FROM astra_tarot30_policy)THEN RAISE(ABORT,'DRAFT_STORAGE_SOFT_CAP')END;
END;
DROP TRIGGER IF EXISTS astra_tarot30_offer_post;
CREATE TRIGGER astra_tarot30_offer_post AFTER INSERT ON astra_tarot25_offers29 BEGIN
 INSERT INTO astra_tarot30_requests VALUES(NEW.telegram_id,NEW.generation,NEW.request_key,NEW.update_id,NEW.offer_id,NEW.spread_id,NEW.theme,NEW.created_at,1);
 UPDATE astra_tarot31_intents SET state='sealed',lease=NULL,lease_until=0 WHERE offer_id=NEW.offer_id;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_purchase_guard BEFORE INSERT ON astra_tarot25_purchases29 WHEN EXISTS(SELECT 1 FROM astra_tarot31_receipts WHERE offer_id=NEW.offer_id)AND NOT EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=NEW.offer_id)BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE i.offer_id=NEW.offer_id AND i.state='sealed' AND i.expires_at>unixepoch() AND p.enabled=1 AND p.revision=i.intent_revision AND s.write_enabled=1)THEN RAISE(ABORT,'INTENT_PAYMENT_GATE')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_purchase_post AFTER INSERT ON astra_tarot25_purchases29 WHEN EXISTS(SELECT 1 FROM astra_tarot31_intents WHERE offer_id=NEW.offer_id)BEGIN
 UPDATE astra_tarot31_intents SET state='paid',lease=NULL,lease_until=0 WHERE offer_id=NEW.offer_id;
 UPDATE astra_tarot31_burst SET used=max(used-1,0)WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND window=(SELECT created_at/60 FROM astra_tarot31_intents WHERE offer_id=NEW.offer_id);
 DELETE FROM astra_tarot31_questions WHERE offer_id=NEW.offer_id;
END;
CREATE TABLE IF NOT EXISTS astra_tarot31_gc(token TEXT PRIMARY KEY NOT NULL CHECK(length(token)=32 AND token NOT GLOB '*[^a-f0-9]*'),limit_rows INTEGER NOT NULL CHECK(typeof(limit_rows)='integer' AND limit_rows BETWEEN 1 AND 20),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0),retention_seconds INTEGER NOT NULL CHECK(typeof(retention_seconds)='integer' AND retention_seconds BETWEEN 3600 AND 2592000),started_at INTEGER NOT NULL DEFAULT(unixepoch()),finished_at INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0 CHECK(typeof(deleted)='integer' AND deleted BETWEEN 0 AND 20));
CREATE TRIGGER IF NOT EXISTS astra_tarot31_gc_insert BEFORE INSERT ON astra_tarot31_gc BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_gc WHERE token=NEW.token AND(limit_rows<>NEW.limit_rows OR revision<>NEW.revision OR retention_seconds<>NEW.retention_seconds))THEN RAISE(ABORT,'GC_TOKEN_MISMATCH')END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_gc WHERE token=NEW.token)THEN RAISE(IGNORE)END;
 SELECT CASE WHEN NEW.started_at<>unixepoch() OR NEW.finished_at<>0 OR NEW.deleted<>0 OR NOT EXISTS(SELECT 1 FROM astra_tarot31_policy p JOIN astra_tarot30_policy s ON s.singleton=1 WHERE p.singleton=1 AND p.migration_done=1 AND p.cleanup_enabled=1 AND s.cleanup_enabled=1 AND NEW.revision=p.revision AND NEW.retention_seconds=s.retention_seconds AND NEW.limit_rows<=s.batch_limit)THEN RAISE(ABORT,'INTENT_GC_DISABLED')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_intent_delete BEFORE DELETE ON astra_tarot31_intents WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN
 SELECT CASE WHEN OLD.state='paid' OR EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=OLD.offer_id) OR EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=OLD.offer_id) OR OLD.expires_at+(SELECT retention_seconds FROM astra_tarot30_policy)>unixepoch() OR NOT EXISTS(SELECT 1 FROM astra_tarot31_gc r JOIN astra_tarot31_policy p ON p.singleton=1 WHERE r.finished_at=0 AND r.started_at=unixepoch() AND r.deleted<r.limit_rows AND p.cleanup_enabled=1)THEN RAISE(ABORT,'INTENT_DELETE_AUTHORITY')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_intent_erased AFTER DELETE ON astra_tarot31_intents BEGIN
 DELETE FROM astra_tarot31_questions WHERE offer_id=OLD.offer_id;
 UPDATE astra_tarot31_gc SET deleted=deleted+1 WHERE finished_at=0 AND started_at=unixepoch() AND EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id);
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_gc_update BEFORE UPDATE ON astra_tarot31_gc BEGIN
 SELECT CASE WHEN OLD.finished_at<>0 OR NEW.token<>OLD.token OR NEW.limit_rows<>OLD.limit_rows OR NEW.revision<>OLD.revision OR NEW.retention_seconds<>OLD.retention_seconds OR NEW.started_at<>OLD.started_at OR NEW.deleted<OLD.deleted OR NEW.deleted>NEW.limit_rows OR(NEW.finished_at<>0 AND NEW.finished_at<>unixepoch())THEN RAISE(ABORT,'GC immutable')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_gc_delete BEFORE DELETE ON astra_tarot31_gc BEGIN SELECT RAISE(ABORT,'GC aggregate immutable');END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_gc_execute AFTER INSERT ON astra_tarot31_gc BEGIN
 DELETE FROM astra_tarot31_intents WHERE offer_id IN(SELECT i.offer_id FROM astra_tarot31_intents i JOIN astra_users u USING(telegram_id) JOIN astra_user_policy g USING(telegram_id) WHERE g.generation=i.generation AND i.state<>'paid' AND i.expires_at+NEW.retention_seconds<=unixepoch() AND NOT EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=i.offer_id) AND NOT EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=i.offer_id)ORDER BY i.expires_at,i.offer_id LIMIT NEW.limit_rows);
 DELETE FROM astra_tarot31_burst WHERE(telegram_id,generation,window)IN(SELECT telegram_id,generation,window FROM astra_tarot31_burst WHERE window<unixepoch()/60-10 ORDER BY window LIMIT(SELECT limit_rows-deleted FROM astra_tarot31_gc WHERE token=NEW.token));
 UPDATE astra_tarot31_gc SET finished_at=unixepoch()WHERE token=NEW.token;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_erase AFTER DELETE ON astra_users BEGIN
 DELETE FROM astra_tarot31_intents WHERE telegram_id=OLD.telegram_id;
 DELETE FROM astra_tarot31_receipts WHERE telegram_id=OLD.telegram_id;
 DELETE FROM astra_tarot31_burst WHERE telegram_id=OLD.telegram_id;
END;

CREATE TRIGGER IF NOT EXISTS astra_tarot31_burst_insert BEFORE INSERT ON astra_tarot31_burst BEGIN
 SELECT CASE WHEN NEW.window<>unixepoch()/60 OR NEW.used<>1 OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_user_policy g USING(telegram_id) WHERE i.telegram_id=NEW.telegram_id AND i.generation=NEW.generation AND g.generation=i.generation AND i.created_at=unixepoch())THEN RAISE(ABORT,'BURST_AUTHORITY')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_burst_update BEFORE UPDATE ON astra_tarot31_burst BEGIN
 SELECT CASE WHEN NEW.telegram_id<>OLD.telegram_id OR NEW.generation<>OLD.generation OR NEW.window<>OLD.window OR NOT(NEW.used=OLD.used+1 AND NEW.window=unixepoch()/60 OR NEW.used=max(OLD.used-1,0) AND EXISTS(SELECT 1 FROM astra_tarot25_purchases29 p JOIN astra_tarot31_intents i USING(offer_id) WHERE p.telegram_id=OLD.telegram_id AND p.generation=OLD.generation AND i.created_at/60=OLD.window AND p.created_at=unixepoch()))THEN RAISE(ABORT,'BURST_TRANSITION')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_burst_delete BEFORE DELETE ON astra_tarot31_burst WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN
 SELECT CASE WHEN OLD.window>=unixepoch()/60-10 OR NOT EXISTS(SELECT 1 FROM astra_tarot31_gc WHERE finished_at=0 AND started_at=unixepoch() AND deleted<limit_rows)THEN RAISE(ABORT,'BURST_DELETE_AUTHORITY')END;
END;
CREATE TRIGGER IF NOT EXISTS astra_tarot31_burst_erased AFTER DELETE ON astra_tarot31_burst WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN UPDATE astra_tarot31_gc SET deleted=deleted+1 WHERE finished_at=0 AND started_at=unixepoch();END;
